contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint fund) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= fund);
        // fund c via Command targeting c itself with empty data (hits receive)
        c.Command(address(c), ""); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;
        uint ownerBefore = address(this).balance;
        c.withdraw(); if (__ESBMC_reverted()) return;
        assert(address(c).balance == 0 && address(this).balance == ownerBefore + balBefore);
    }
    receive() external payable {}
}

