// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX3 c;

    function setUp() public {
        c = new MultiplicatorX3();
    }

    function _run(uint256 fund) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= fund);
        try c.Command(address(c), "") {} catch { return; }
        uint balBefore = address(c).balance;
        uint ownerBefore = address(this).balance;
        try c.withdraw() {} catch { return; }
        assertTrue(address(c).balance == 0 && address(this).balance == ownerBefore + balBefore);
    }

    function testFuzz_run(uint256 fund) public {
        _run(fund);
    }

    receive() external payable {}
}
